def _duration(seconds: float) -> str:
    seconds = int(float(seconds or 0))
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    if h:
        return f"{h} h {m:02d} min"
    if m:
        return f"{m} min {s:02d} s"
    return f"{s} s"


def _format_de_number(value: Any, digits: int = 1, *, trim: bool = True) -> str:
    if value in (None, ""):
        return "-"
    try:
        number = float(value)
    except Exception:
        return str(value)
    text = f"{number:,.{max(0, digits)}f}"
    if trim and digits > 0:
        text = text.rstrip("0").rstrip(".")
    return text.replace(",", "X").replace(".", ",").replace("X", ".")


def _num(value: Any, suffix: str = "", digits: int = 1, *, trim: bool = True) -> str:
    return f"{_format_de_number(value, digits, trim=trim)}{suffix}"


def _kwh(value: Any) -> str: return _num(value, " kWh", 4, trim=False)
def _w(value: Any) -> str: return _num(value, " W", 1, trim=True)
def _pct(value: Any) -> str: return _num(value, " %", 1, trim=True)
def _per_hour(value: Any) -> str: return _num(value, " / h", 1, trim=True)


def _states_summary(states: Dict[str, Any]) -> str:
    order = ["ok", "suspect", "limited", "not_accepting"]
    labels = {"ok": "ok", "suspect": "Verdacht", "limited": "begrenzt", "not_accepting": "nimmt nicht an"}
    parts = [f"{labels[k]}: {states.get(k, 0)}" for k in order if k in states]
    parts += [f"{k}: {states.get(k, 0)}" for k in sorted(k for k in states if k not in order)]
    return ", ".join(parts) if parts else "keine Daten"


def _stringify_mapping(value: Dict[str, Any]) -> str:
    if set(value.keys()) & {"ok", "suspect", "limited", "not_accepting"}:
        return _states_summary(value)
    return ", ".join(f"{key}: {val}" for key, val in sorted(value.items()))


def _label_cell(label: str) -> SafeHtml:
    label_text = str(label)
    help_text = TERM_HELP.get(label_text)
    escaped = html.escape(label_text)
    if not help_text:
        return SafeHtml(escaped)
    return SafeHtml(f"<span>{escaped}</span> <details class='term-info'><summary>info</summary><div>{html.escape(help_text)}</div></details>")


def _cell(value: Any) -> str:
    if isinstance(value, SafeHtml):
        return str(value)
    if isinstance(value, dict):
        return html.escape(_stringify_mapping(value))
    if isinstance(value, (list, tuple)):
        return html.escape(", ".join(_stringify_mapping(v) if isinstance(v, dict) else str(v) for v in value))
    return html.escape(str(value))


def _table(rows: Iterable[Tuple[str, Any]]) -> str:
    return "".join(f"<tr><th>{_label_cell(str(label))}</th><td>{_cell(value)}</td></tr>" for label, value in rows)


def _th(label: str) -> str: return str(_label_cell(label))


def _rating_badge(value: str) -> SafeHtml:
    cls = {"green": "ok", "yellow": "warn", "red": "bad", "ok": "ok", "warning": "warn", "error": "bad"}.get(value, "neutral")
    label = {"green": "grün", "yellow": "gelb", "red": "rot", "ok": "ok", "warning": "Warnung", "error": "Fehler"}.get(value, value)
    return SafeHtml(f"<span class='badge {cls}'>{html.escape(label)}</span>")


def _bar(label: str, value: float, max_value: float, css: str = "bar") -> SafeHtml:
    width = 0 if max_value <= 0 else max(0.0, min(100.0, float(value) / max_value * 100.0))
    return SafeHtml(f"<div class='barrow'><span>{html.escape(label)}</span><div class='barbox'><div class='{css}' style='width:{width:.1f}%'></div></div><b>{_format_de_number(value, 1)}</b></div>")


def _bars(items: List[Tuple[str, float]], css: str = "bar") -> SafeHtml:
    if not items:
        return SafeHtml("<p>Keine Diagrammdaten.</p>")
    max_value = max([abs(float(v or 0)) for _, v in items] + [1.0])
    return SafeHtml("".join(str(_bar(label, float(value or 0), max_value, css)) for label, value in items))


def summary_cards(result: Dict[str, Any]) -> str:
    ratings = result.get("summary_ratings") or {}
    labels = [
        ("fair_regulator_quality", "Reglerqualität"), ("actuator_reserve", "Stellreserve"),
        ("zendure_tracking", "Soll/Ist"), ("deadband", "Deadband"),
        ("mqtt_command_effect", "MQTT-Wirkung"), ("oscillation", "Oszillation"),
        ("cross_charge", "Cross-Charge"), ("data_quality", "Datenqualität"),
    ]
    cards = []
    for key, label in labels:
        cards.append(f"<div class='card'><div>{html.escape(label)}</div>{_rating_badge(str(ratings.get(key, '-')))}</div>")
    return "".join(cards)


def recommendations_table(result: Dict[str, Any]) -> str:
    recs = result.get("recommendations") or []
    if not recs:
        return "<tr><td>Keine Empfehlungen erzeugt.</td></tr>"
    rows = f"<tr><th>{_th('Schwere')}</th><th>Thema</th><th>Empfehlung</th></tr>"
    for rec in recs:
        rows += f"<tr><td>{_rating_badge(str(rec.get('severity','neutral')))}</td><td>{html.escape(str(rec.get('topic','-')))}</td><td>{html.escape(str(rec.get('text','-')))}</td></tr>"
    return rows


def overview_table(result: Dict[str, Any]) -> str:
    dq = result.get("data_quality") or {}
    return _table([
        ("Dateien", ", ".join(result.get("filenames") or [result.get("filename", "-")])),
        ("Datenzeilen", result.get("rows", 0)),
        ("Zeitraum", f"{result.get('period_start', '-')} bis {result.get('period_end', '-')}"),
        ("Dauer", _duration(result.get("duration_seconds", 0))),
        ("Datenqualität", _rating_badge("green" if dq.get("status") == "ok" else ("red" if dq.get("status") == "error" else "yellow"))),
        ("Ø / Median / max dt_s", f"{_num(dq.get('avg_dt_s', 0), '', 3)} / {_num(dq.get('median_dt_s', 0), '', 3)} / {_num(dq.get('max_dt_s', 0), ' s', 3)}"),
    ])


