def events_table(result: Dict[str, Any], limit: int = 120) -> str:
    events: List[Dict[str, Any]] = list(result.get("events") or [])[:limit]
    if not events:
        return "<tr><td>Keine auffälligen Ereignisse erkannt.</td></tr>"
    rows = f"<tr><th>{_th('Zeit')}</th><th>{_th('Schwere')}</th><th>{_th('Typ')}</th><th>{_th('Ereignis')}</th></tr>"
    for event in events:
        rows += f"<tr><td>{html.escape(str(event.get('time', '-')))}</td><td>{html.escape(str(event.get('severity', '-')))}</td><td>{html.escape(str(event.get('type', '-')))}</td><td>{html.escape(str(event.get('text', '-')))}</td></tr>"
    return rows


def charts_html(result: Dict[str, Any]) -> str:
    fq = result.get("fair_regulator_quality") or {}
    db = result.get("deadband") or {}
    ce = result.get("command_efficiency") or {}
    state_items = [(str(i.get("mode")), float(i.get("seconds", 0))) for i in (result.get("operating_state_matrix") or [])[:8]]
    html_parts = [
        "<div class='chartgrid'>",
        "<div><h4>Abweichungsursachen</h4>" + str(_bars([("beeinflussbar", fq.get("controllable_percent", 0)), ("nicht beeinflussbar", fq.get("non_controllable_percent", 0))], "bar")) + "</div>",
        "<div><h4>Deadband</h4>" + str(_bars([("Deadband", db.get("inside_deadband_percent", 0)), ("erweitert", db.get("inside_extended_band_percent", 0)), ("außerhalb mit Reserve", db.get("outside_deadband_with_reserve_percent", 0))], "bar")) + "</div>",
        "<div><h4>Betriebszustände</h4>" + str(_bars(state_items, "bar")) + "</div>",
        "<div><h4>MQTT-Wirkung</h4>" + str(_bars([("verbessert", ce.get("improved_count", 0)), ("neutral", ce.get("neutral_count", 0)), ("verschlechtert", ce.get("worse_count", 0)), ("nicht bewertbar", ce.get("unknown_count", 0))], "bar")) + "</div>",
        "</div>",
    ]
    return "".join(html_parts)


def text_report(result: Dict[str, Any]) -> str:
    fq = result.get("fair_regulator_quality") or {}; ce = result.get("command_efficiency") or {}; db = result.get("deadband") or {}
    lines = [
        f"Zendure Energy Controller CSV-Analyse V{REPORT_VERSION}", "============================================",
        f"Dateien: {', '.join(result.get('filenames') or [result.get('filename', '-')])}", f"Schema: {result.get('schema', '-')}",
        f"Datenzeilen: {result.get('rows', 0)}", f"Zeitraum: {result.get('period_start', '-')} bis {result.get('period_end', '-')}", f"Dauer: {_duration(result.get('duration_seconds', 0))}",
        "", "Kurzfazit / Empfehlungen", "------------------------",
    ]
    for rec in result.get("recommendations", []):
        lines.append(f"[{rec.get('severity','-')}] {rec.get('topic','-')}: {rec.get('text','-')}")
    lines += ["", "Faire Reglerqualität", "---------------------",
        f"Gesamt Ø |Netz|: {_w(fq.get('total_avg_abs_grid_w',0))}",
        f"Beeinflussbare Ø aktiv: {_w(fq.get('controllable_active_avg_abs_grid_w',0))}",
        f"Nicht beeinflussbarer Anteil: {_pct(fq.get('non_controllable_percent',0))}",
        f"Kompatibilität Ø |Netz|: {_w((result.get('regulator_quality') or {}).get('avg_abs_grid_w', fq.get('total_avg_abs_grid_w',0)))}",
        "", "Energiefluss", "------------",
        f"Netzbezug: {_kwh((result.get('energy') or {}).get('grid_import_kwh', result.get('grid_import_kwh', 0)))}",
        f"Netzeinspeisung: {_kwh((result.get('energy') or {}).get('grid_export_kwh', result.get('grid_export_kwh', 0)))}",
        f"Zendure geladen/entladen: {_kwh((result.get('energy') or {}).get('zendure_charge_kwh', 0))} / {_kwh((result.get('energy') or {}).get('zendure_discharge_kwh', 0))}",
        "", "Deadband / MQTT", "---------------",
        f"Zeit im Deadband: {_pct(db.get('inside_deadband_percent',0))}",
        f"Außerhalb Deadband mit Reserve: {_pct(db.get('outside_deadband_with_reserve_percent',0))}",
        f"MQTT-Kommandos gesamt: {ce.get('commands_total',0)}, pro aktiver Stunde: {_per_hour(ce.get('commands_per_active_hour',0))}",
        "", "Ereignisse", "----------",
    ]
    for event in result.get("events", [])[:80]:
        lines.append(f"{event.get('time', '-')}: [{event.get('severity', '-')}] {event.get('text', '-')}")
    if not result.get("events"):
        lines.append("keine auffälligen Ereignisse")
    return "\n".join(lines) + "\n"


# Compatibility wrapper for older replay_web/tests.
def html_table(result: Dict[str, Any]) -> str:
    return overview_table(result) + fair_regulator_table(result) + cross_charge_table(result)
